arguments.command:
python3 -c "
# Let me be very precise about {x}}
tests = [
    ('{x}}', True),
    ('a{b}c', True),
    ('a{b}}c', True),
]
for fmt, _ in tests:
    try:
        result = fmt.format(x='hello')
        print(f'format({fmt!r}, x=hello) -> {result!r}')
    except Exception as e:
        print(f'format({fmt!r}, x=hello) -> ERROR: {type(e).__name__}: {e}')

print()
# Also check what parse does with these
import sys
sys.path.insert(0, '.')
import parse
for fmt in ['{x}}', 'a{b}c', 'a{b}}c']:
    try:
        result = parse.parse(fmt, 'hello}' if '}' in fmt else 'hello')
        print(f'parse({fmt!r}, ...) -> {result!r}')
    except Exception as e:
        print(f'parse({fmt!r}, ...) -> ERROR: {type(e).__name__}: {e}')
"
